/**
 * Workspace 1: `1 Pulse` (`/pulse`)
 *
 * - 4-KPI Hero Strip (`Active Keepers`, `Tasks Done/24h & Verify`, `Turns/24h`,
 *   `Spend/24h ($0 Sub / $0 Exhausted / ? Unreported)`), zero orphan 7th card,
 *   zero empty `0.000 Candle` box.
 * - Attention Queue Card (pending Approvals / Keeper Asks / Failed Keepers).
 * - Company Fleet 24h Sparklines (`uPlot` synced to global `timeWindow` + 28–36px portrait avatars).
 * - Lightweight Multi-Keeper Team Handoff & Succession Strip (zero Cytoscape).
 * - Active Goals + World Memory / Candle Pulse Digest linking into `/work/*` and `/knowledge/*`.
 */

import { html } from 'htm/preact'
import { goalPhaseSemanticTone, parseCanonicalGoalPhase } from '../../lib/goal-phase-tone'
import { contextSeverityTone } from '../../api/keeper-diagnostics'
import { useCallback, useEffect, useMemo, useRef, useState } from 'preact/hooks'
import {
  formatObserved,
  resourceCache,
  type Observed,
} from '../../core/resource-cache'
import {
  extractObserverTopics,
  markViewSynced,
  subscribeObserverFrames,
  subscribeObserverReconnect,
  subscribeObserverResync,
} from '../../core/observer'
import {
  timeWindow,
  type TimeWindow,
} from '../../core/time-window'
import { currentSessionEpoch, sessionEpoch } from '../../core/auth'
import { KeeperBadge } from '../../components/keeper-badge'
import { RefreshButton } from '../../components/primitives/refresh-button'
import { UPlotChart, type UPlotSeriesSpec } from '../../components/primitives/uplot-chart'
import type { WorkspaceViewProps } from '../types'
import { loadPulseBundle, PULSE_OBSERVER_TOPICS, readPulseBundle } from './pulse-data'
import {
  buildAttentionQueue,
  buildCompanyFleetGroups,
  buildPulseKpis,
  buildTeamHandoffPulse,
  formatApprovalExpiry,
  formatCompactCount,
  formatMilliCandle,
  formatRelativeAge,
  isKeeperActive,
  isKeeperFailing,
  isKeeperPathResting,
  observeKeeperContextPct,
} from './pulse-model'
import type {
  PulseAttentionItem,
  PulseGoalSummary,
  PulseKeeperRow,
} from './types'
import './pulse.css'

const SPARKLINE_SERIES: readonly UPlotSeriesSpec[] = [
  {
    label: 'Turns',
    colorToken: '--brass-1',
    width: 1.75,
    fillAlpha: 0.16,
  },
]

function isPulseKeeperRow(v: unknown): v is PulseKeeperRow {
  return typeof v === 'object' && v !== null && typeof (v as { name?: unknown }).name === 'string'
}

function renderPulseKeeperErrorDetail(row: PulseKeeperRow) {
  const laneFailures = row.runtime_lane_failures ?? []
  const hasBlocker = row.runtime_blocker_summary != null
  const hasPathRest = row.runtime_path_rest != null
  const hasIssue = row.directory_issue != null
  const hasLane = laneFailures.length > 0
  const hasLast = row.last_failure != null
  const hasAny = hasBlocker || hasPathRest || hasIssue || hasLane || hasLast
  return html`
    <div class="pulse-keeper-error">
      <div class="pulse-kv-grid">
        <div class="pulse-kv">
          <span class="pulse-kv-k">Keeper</span>
          <span class="pulse-kv-v">${row.name}</span>
        </div>
        <div class="pulse-kv">
          <span class="pulse-kv-k">health / phase</span>
          <span class="pulse-kv-v">${row.health} / ${row.phase}</span>
        </div>
        <div class="pulse-kv">
          <span class="pulse-kv-k">status</span>
          <span class="pulse-kv-v">${row.status}</span>
        </div>
        <div class="pulse-kv">
          <span class="pulse-kv-k">runtime</span>
          <span class="pulse-kv-v">${row.runtime_id}</span>
        </div>
      </div>
      ${hasAny
        ? html`
          <div class="pulse-keeper-error-body">
            ${row.runtime_blocker_summary && html`
              <div class="pulse-keeper-error-row">
                <strong>차단 사유</strong>: ${row.runtime_blocker_summary}
                ${row.runtime_blocker_signature ? html` <span class="mono">(${row.runtime_blocker_signature})</span>` : null}
                ${row.runtime_blocker_class ? html` <span class="mono">[${row.runtime_blocker_class}]</span>` : null}
              </div>
            `}
            ${row.runtime_path_rest && html`
              <div class="pulse-keeper-error-row">
                <strong>경로 휴식</strong>: ${row.runtime_path_rest.runtime_id ?? row.runtime_id}
                ${row.runtime_path_rest.release_at ? ` · 해제 ${row.runtime_path_rest.release_at}` : ''}
                ${row.runtime_path_rest.release_basis ? ` (${row.runtime_path_rest.release_basis})` : ''}
              </div>
            `}
            ${row.directory_issue && html`
              <div class="pulse-keeper-error-row"><strong>설정 오류</strong>: ${row.directory_issue}</div>
            `}
            ${row.last_failure && html`
              <div class="pulse-keeper-error-row">
                <strong>최근 실패</strong>: ${row.last_failure.cause}
                ${row.last_failure.at_unix != null ? html` <span class="mono">(@${row.last_failure.at_unix})</span>` : null}
              </div>
            `}
            ${hasLane && html`
              <div class="pulse-keeper-error-row">
                <strong>폴백 시도</strong>:
                <div class="pulse-keeper-lane-list">
                  ${laneFailures.map((f, idx) => html`
                    <div class="pulse-keeper-lane" key=${`${f.runtime_id ?? 'lane'}:${f.attempt ?? idx}:${f.summary}`}>
                      <div>
                        <span class="mono">${f.runtime_id ?? 'lane'}${f.fault_kind ? `[${f.fault_kind}]` : ''}${f.dispatch ? ` · ${f.dispatch}` : ''}${f.attempt != null ? ` · attempt ${f.attempt}` : ''}</span>
                      </div>
                      <div>${f.summary}</div>
                      ${f.failure_kind || f.failure_detail || f.provider || f.network_kind
                        ? html`
                          <div class="pulse-keeper-lane-meta">
                            ${f.failure_kind ? html`<span>kind:${f.failure_kind}</span>` : null}
                            ${f.provider ? html`<span>provider:${f.provider}</span>` : null}
                            ${f.network_kind ? html`<span>network:${f.network_kind}</span>` : null}
                            ${f.failure_detail ? html`<span class="mono">${f.failure_detail}</span>` : null}
                          </div>
                        `
                        : null}
                    </div>
                  `)}
                </div>
              </div>
            `}
            ${(row.operator_disposition && row.operator_disposition !== 'pass') || row.next_action
              ? html`
                <div class="pulse-keeper-error-row">
                  ${(row.operator_disposition && row.operator_disposition !== 'pass')
                    ? html`<span><strong>조치</strong>: ${row.operator_disposition}${row.operator_disposition_reason ? ` (${row.operator_disposition_reason})` : ''}</span>`
                    : null}
                  ${row.next_action ? html`<span><strong>다음 단계</strong>: ${row.next_action}</span>` : null}
                </div>
              `
              : null}
          </div>
        `
        : html`<div class="pulse-empty">표시할 오류 상세 없음 (summary/signature/lane/last_failure 모두 없음)</div>`}
    </div>
  `
}

function goalPhaseTone(phase: string): 'ok' | 'warn' | 'bad' | 'info' | 'brass' | 'default' {
  const canonical = parseCanonicalGoalPhase(phase)
  if (canonical === null) return 'default'
  switch (goalPhaseSemanticTone(canonical)) {
    case 'ok': return 'ok'
    case 'info': return 'info'
    case 'stalled': return 'brass'
    case 'warn': return 'warn'
    case 'err': return 'bad'
    case 'idle': return 'default'
  }
}

function keeperCtxTone(obs: Observed<number>): 'ok' | 'warn' | 'bad' | 'default' {
  if (obs.kind !== 'value') return 'default'
  const tone = contextSeverityTone(obs.data)
  return tone === 'absent' ? 'default' : tone
}

export function PulseWorkspace(props: WorkspaceViewProps) {
  const win: TimeWindow = timeWindow.value
  const epoch = sessionEpoch.value
  const bundle = readPulseBundle(win)
  const [observedAtSec, setObservedAtSec] = useState<number>(() => Math.floor(Date.now() / 1000))
  const [openSparklines, setOpenSparklines] = useState<ReadonlySet<string>>(() => new Set())
  const mountedRef = useRef(true)

  useEffect(() => {
    mountedRef.current = true
    return () => {
      mountedRef.current = false
    }
  }, [])

  const refresh = useCallback(async (reason: 'mount' | 'route' | 'sse' | 'manual') => {
    const startEpoch = currentSessionEpoch()
    const refreshWindow = timeWindow.peek()
    await loadPulseBundle(refreshWindow, reason)
    if (!mountedRef.current || currentSessionEpoch() !== startEpoch || timeWindow.peek() !== refreshWindow) return
    setObservedAtSec(Math.floor(Date.now() / 1000))
    markViewSynced()
  }, [])

  useEffect(() => {
    void refresh('mount')
  }, [win, epoch, refresh])

  useEffect(() => {
    let timer: ReturnType<typeof setTimeout> | null = null
    const unsub = subscribeObserverFrames((frame) => {
      const topics = extractObserverTopics(frame)
      let relevant = false
      for (let i = 0; i < topics.length; i++) {
        if (PULSE_OBSERVER_TOPICS.has(topics[i]!)) {
          relevant = true
          break
        }
      }
      if (!relevant) return
      if (timer) return
      timer = setTimeout(() => {
        timer = null
        void refresh('sse')
      }, 450)
    })
    const unsubReconnect = subscribeObserverReconnect(() => {
      void refresh('sse')
    })
    const unsubResync = subscribeObserverResync(() => {
      resourceCache.invalidateAll()
      void refresh('sse')
    })
    return () => {
      unsub()
      unsubReconnect()
      unsubResync()
      if (timer) clearTimeout(timer)
    }
  }, [refresh])

  const nowSec = observedAtSec

  const kpis = useMemo(
    () =>
      buildPulseKpis({
        shell: bundle.shell,
        keepers: bundle.keepers,
        costs: bundle.costs,
        usage: bundle.usage,
        window: win,
        nowSec,
      }),
    [bundle.shell, bundle.keepers, bundle.costs, bundle.usage, win, nowSec],
  )

  const keepersList: readonly PulseKeeperRow[] = bundle.keepers.kind === 'value' ? bundle.keepers.data : []
  const knownKeeperSet = useMemo(() => new Set(keepersList.map((k) => k.name)), [keepersList])

  const attentionItems = useMemo<readonly PulseAttentionItem[]>(
    () =>
      buildAttentionQueue({
        approvals: bundle.approvals.kind === 'value' ? bundle.approvals.data : [],
        asks: bundle.asks.kind === 'value' ? bundle.asks.data : [],
        keepers: keepersList,
        nowSec,
      }),
    [bundle.approvals, bundle.asks, keepersList, nowSec],
  )

  const fleetGroups = useMemo(
    () =>
      buildCompanyFleetGroups({
        keepers: keepersList,
        shellGroups: bundle.shell.kind === 'value' ? bundle.shell.data.groups : [],
        window: win,
        nowSec,
      }),
    [keepersList, bundle.shell, win, nowSec],
  )

  const handoffs = useMemo(
    () =>
      buildTeamHandoffPulse(
        bundle.board.kind === 'value' ? bundle.board.data : [],
        keepersList,
        8,
      ),
    [bundle.board, keepersList],
  )

  const goalsSnapshot = bundle.goals.kind === 'value' ? bundle.goals.data : null
  const activeGoals = useMemo<readonly PulseGoalSummary[]>(() => {
    if (goalsSnapshot === null || goalsSnapshot.state !== 'ready') return []
    return goalsSnapshot.goals
      .filter((g) => {
        // A goal without a phase is not known to be finished, so it stays listed.
        const p = g.phase?.toLowerCase() ?? null
        return p !== 'completed' && p !== 'dropped'
      })
      .slice(0, 6)
  }, [goalsSnapshot])

  const candleDigest = bundle.candle.kind === 'value' ? bundle.candle.data : null
  const showCandleBalance =
    candleDigest !== null
    && candleDigest.policy_configuration === 'enabled'
    && (candleDigest.total_events > 0 || candleDigest.circulating_milli !== '0')

  const attentionErrors: string[] = []
  if (bundle.approvals.kind === 'failed') attentionErrors.push(`도구 승인 조회 실패: ${bundle.approvals.error.message}`)
  if (bundle.asks.kind === 'failed') attentionErrors.push(`Keeper 질문 조회 실패: ${bundle.asks.error.message}`)
  if (bundle.keepers.kind === 'failed') attentionErrors.push(`Keeper 상태 조회 실패: ${bundle.keepers.error.message}`)
  const attentionUnchecked: string[] = []
  if (bundle.approvals.kind === 'absent' || bundle.approvals.kind === 'unreported') {
    attentionUnchecked.push(
      bundle.approvals.kind === 'absent' && bundle.approvals.reason === 'multi_account_unbridged'
        ? '도구 승인 (멀티 계정 미지원)'
        : '도구 승인 (미확인)',
    )
  }
  if (bundle.asks.kind === 'absent' || bundle.asks.kind === 'unreported') {
    attentionUnchecked.push(
      bundle.asks.kind === 'absent' && bundle.asks.reason === 'multi_account_unbridged'
        ? 'Keeper 질문 (멀티 계정 미지원)'
        : 'Keeper 질문 (미확인)',
    )
  }
  if (bundle.keepers.kind === 'absent' || bundle.keepers.kind === 'unreported') {
    attentionUnchecked.push(
      bundle.keepers.kind === 'absent' && bundle.keepers.reason === 'multi_account_unbridged'
        ? 'Keeper 상태 (멀티 계정 미지원)'
        : 'Keeper 상태 (미확인)',
    )
  }
  const attentionLoading =
    bundle.approvals.kind === 'loading' || bundle.asks.kind === 'loading' || bundle.keepers.kind === 'loading'
  const attentionStale =
    (bundle.approvals.kind === 'value' && bundle.approvals.stale)
    || (bundle.asks.kind === 'value' && bundle.asks.stale)
    || (bundle.keepers.kind === 'value' && bundle.keepers.stale)
  const attentionPillTone: 'bad' | 'warn' | 'info' | 'ok' =
    attentionErrors.length > 0
      ? 'bad'
      : attentionItems.length > 0 || attentionUnchecked.length > 0
        ? 'warn'
        : attentionLoading
          ? 'info'
          : 'ok'
  const attentionPillText =
    attentionErrors.length > 0
      ? '조회 오류'
      : attentionUnchecked.length > 0
        ? (attentionItems.length > 0 ? `${attentionItems.length}건 · 일부 미확인` : '일부 미확인')
        : attentionLoading && attentionItems.length === 0
          ? '확인 중'
          : `${attentionItems.length}건`

  const worldMemory = bundle.worldMemory.kind === 'value' ? bundle.worldMemory.data : null

  return html`
    <div class="pulse-root" data-workspace="pulse">
      <header class="pulse-header">
        <div class="pulse-header-title">
          <span class="ov-eyebrow">1 PULSE · OPERATIONS OVERVIEW</span>
          <h1>Fleet Pulse</h1>
        </div>
        <div class="pulse-header-meta">
          <${RefreshButton} onRefresh=${() => refresh('manual')} />
        </div>
      </header>

      <!-- 4-KPI Hero Strip -->
      <section class="pulse-kpis" aria-label="핵심 지표">
        ${kpis.map((kpi) => {
          const text = formatObserved(kpi.value)
          const isAbsent = kpi.value.kind === 'absent' || kpi.value.kind === 'unreported'
          return html`
            <button
              key=${kpi.id}
              type="button"
              class="pulse-kpi"
              data-kpi-id=${kpi.id}
              title=${kpi.exactTooltip ?? text}
              onClick=${() => props.onNavigate(kpi.route)}
            >
              <span class="pulse-kpi-label">${kpi.label}</span>
              <span
                class="pulse-kpi-value tnum"
                data-tone=${kpi.tone}
                data-absent=${isAbsent ? 'true' : 'false'}
              >
                ${text}
              </span>
              <span class="pulse-kpi-sub">${kpi.secondary ?? '상세 보기 →'}</span>
            </button>
          `
        })}
      </section>

      <div class="pulse-grid">
        <div class="pulse-col">
          <!-- Company Fleet 24h Sparklines -->
          <section class="pulse-card" aria-label="회사별 Keeper 플릿">
            <div class="pulse-card-head">
              <div class="pulse-card-title-group">
                <h2>Company Fleet · 24h Activity</h2>
                <span class="pulse-pill" data-tone="warn" data-stale=${bundle.keepers.kind === 'value' && bundle.keepers.stale ? 'true' : 'false'} aria-hidden=${bundle.keepers.kind === 'value' && bundle.keepers.stale ? undefined : 'true'}>지연됨</span>
              </div>
              <button type="button" class="btn-ghost" onClick=${() => props.onNavigate('/keepers')}>
                전체 Keeper →
              </button>
            </div>
            ${bundle.keepers.kind === 'loading'
              ? html`<div class="pulse-empty">플릿 상태 불러오는 중…</div>`
              : bundle.keepers.kind === 'failed'
                ? html`<div class="ap-error" role="alert">플릿 조회 실패: ${bundle.keepers.error.message}</div>`
                : bundle.keepers.kind === 'absent' && bundle.keepers.reason === 'multi_account_unbridged'
                  ? html`<div class="pulse-empty" data-testid="pulse-fleet-multi-account-unbridged" role="status">멀티 계정 모드에서는 로컬 Keeper 플릿을 조회하지 않습니다.</div>`
                  : bundle.keepers.kind === 'absent' || bundle.keepers.kind === 'unreported'
                    ? html`<div class="pulse-empty">${formatObserved(bundle.keepers)}</div>`
                    : fleetGroups.length === 0
                      ? html`<div class="pulse-empty">등록된 Keeper 없음</div>`
                      : html`
                      <div class="pulse-fleet-groups">
                        ${fleetGroups.map((group) => {
                          const turnFmt = formatCompactCount(group.turnsInWindow)
                          const okTurns = group.okTurnsInWindow ?? group.turnsInWindow
                          const restedTurns = group.restedTurnsInWindow ?? 0
                          const failedTurns = group.failedTurnsInWindow ?? 0
                          const restingCount = group.restingCount ?? 0
                          return html`
                            <article key=${group.company} class="pulse-fleet-group">
                              <div class="pulse-fleet-group-head">
                                <span class="pulse-fleet-group-name">${group.company}</span>
                                <div class="pulse-header-meta">
                                  <span class="pulse-pill" data-tone=${group.activeCount > 0 ? 'ok' : 'default'}>
                                    ${group.activeCount}/${group.keepers.length} active
                                  </span>
                                  ${group.failingCount > 0 && html`
                                    <span class="pulse-pill" data-tone="bad">
                                      ⚠ ${group.failingCount} fault
                                    </span>
                                  `}
                                  ${restingCount > 0 && html`
                                    <span class="pulse-pill" data-tone="warn">
                                      ⏸ ${restingCount} rest
                                    </span>
                                  `}
                                  ${failedTurns > 0 && html`
                                    <span class="pulse-pill" data-tone="bad" title=${`성공 ${okTurns} · 휴식 ${restedTurns} · 실패 ${failedTurns}`}>
                                      ✕ ${formatCompactCount(failedTurns).short} fail
                                    </span>
                                  `}
                                  <span
                                    class="pulse-pill"
                                    data-tone="brass"
                                    title=${`24h 턴 총 ${turnFmt.exact} (성공 ${okTurns} · 휴식 ${restedTurns} · 실패 ${failedTurns})`}
                                  >
                                    ${turnFmt.short} turns/24h
                                  </span>
                                </div>
                              </div>

                              <div class="pulse-keeper-grid">
                                ${group.keepers.map((k) => {
                                  const ctxObs = observeKeeperContextPct(k)
                                  const isEstimated = k.context_ratio == null && k.context_provenance === 'estimated' && k.estimated_context_ratio != null
                                  const ctxText = ctxObs.kind === 'value'
                                    ? `${isEstimated ? '~' : ''}${ctxObs.data}%`
                                    : formatObserved(ctxObs, (v) => `${v}%`)
                                  const ctxTitle = k.context_tokens != null && k.context_max != null
                                    ? `${k.context_tokens.toLocaleString('en-US')} / ${k.context_max.toLocaleString('en-US')} tok`
                                    : isEstimated
                                      ? `추정 컨텍스트 (~${ctxObs.kind === 'value' ? ctxObs.data : '?'}%)`
                                      : k.context_unavailable_reason
                                        ? `컨텍스트 미측정 (${k.context_unavailable_reason})`
                                        : 'Context 비율'
                                  const active = isKeeperActive(k)
                                  const failing = isKeeperFailing(k)
                                  const resting = !failing && isKeeperPathResting(k)
                                  const tileSub = failing
                                    ? `⚠ ${k.runtime_blocker_summary ?? k.last_failure?.cause ?? k.directory_issue ?? k.health}`
                                    : resting
                                      ? `⏸ 휴식${k.runtime_path_rest?.runtime_id ? ` · ${k.runtime_path_rest.runtime_id}` : ''}`
                                      : k.paused
                                        ? 'paused'
                                        : k.phase
                                  return html`
                                    <button
                                      key=${k.name}
                                      type="button"
                                      class="pulse-keeper-tile"
                                      title=${tileSub}
                                      onClick=${() => props.onNavigate(`/keepers/${encodeURIComponent(k.name)}/chat`)}
                                    >
                                      <div class="pulse-keeper-tile-left">
                                        <${KeeperBadge}
                                          id=${k.name}
                                          size="md"
                                          variant="sigil"
                                          portrait=${true}
                                          beat=${active}
                                        />
                                        <div class="pulse-keeper-tile-meta">
                                          <span class="pulse-keeper-tile-name">${k.name}</span>
                                          <span class="pulse-keeper-tile-sub">
                                            ${tileSub}
                                          </span>
                                        </div>
                                      </div>
                                      <span
                                        class="pulse-pill"
                                        data-ctx="true"
                                        data-tone=${keeperCtxTone(ctxObs)}
                                        title=${ctxTitle}
                                      >
                                        Ctx ${ctxText}
                                      </span>
                                    </button>
                                  `
                                })}
                              </div>

                              <details
                                class="ap-disclosure pulse-spark-disclosure"
                                data-testid="pulse-sparkline-disclosure"
                                open=${openSparklines.has(group.company) || undefined}
                                onToggle=${(e: Event) => {
                                  const nextOpen = (e.currentTarget as HTMLDetailsElement).open
                                  setOpenSparklines((prev) => {
                                    if (prev.has(group.company) === nextOpen) return prev
                                    const next = new Set(prev)
                                    if (nextOpen) next.add(group.company)
                                    else next.delete(group.company)
                                    return next
                                  })
                                }}
                              >
                                <summary class="ap-disclosure-trigger">
                                  <span>추이 보기 · ${group.company} (${turnFmt.short} turns/24h)</span>
                                  <span aria-hidden="true">${openSparklines.has(group.company) ? '▾' : '▸'}</span>
                                </summary>
                                <div class="ap-disclosure-body">
                                  ${openSparklines.has(group.company) && html`
                                    <div class="pulse-spark-wrap">
                                      <${UPlotChart}
                                        id=${`pulse-spark-${group.company}`}
                                        title=${`${group.company} · 24h 턴 추이`}
                                        data=${group.sparklineData}
                                        series=${SPARKLINE_SERIES}
                                        height=${92}
                                        syncCrosshair=${true}
                                        emptyLabel="해당 구간 턴 기록 없음"
                                      />
                                    </div>
                                  `}
                                </div>
                              </details>
                            </article>
                          `
                        })}
                      </div>
                    `}
          </section>

          <!-- Multi-Keeper Team Handoff & Succession Strip (Zero Cytoscape) -->
          <section class="pulse-card" aria-label="팀 핸드오프 및 협업 펄스">
            <div class="pulse-card-head">
              <div class="pulse-card-title-group">
                <h2>Team Handoff & Succession Pulse</h2>
                <span class="pulse-pill" data-tone="warn" data-stale=${bundle.board.kind === 'value' && bundle.board.stale ? 'true' : 'false'} aria-hidden=${bundle.board.kind === 'value' && bundle.board.stale ? undefined : 'true'}>지연됨</span>
              </div>
              <button type="button" class="btn-ghost" onClick=${() => props.onNavigate('/knowledge/board')}>
                Board 열기 →
              </button>
            </div>
            ${bundle.board.kind === 'loading'
              ? html`<div class="pulse-empty">Board 신호 불러오는 중…</div>`
              : bundle.board.kind === 'failed'
                ? html`<div class="ap-error" role="alert">Board 조회 실패: ${bundle.board.error.message}</div>`
                : handoffs.length === 0
                  ? html`<div class="pulse-empty">최근 다중 Keeper 핸드오프/승계 신호 없음</div>`
                  : html`
                  <div class="pulse-handoff-list">
                    ${handoffs.map((h) => html`
                      <button
                        key=${h.id}
                        type="button"
                        class="pulse-handoff-row"
                        onClick=${() => props.onNavigate(h.route)}
                      >
                        <${KeeperBadge} id=${h.fromKeeper} size="sm" portrait=${knownKeeperSet.has(h.fromKeeper)} />
                        ${h.toKeepers.length > 0 && html`
                          <span class="pulse-handoff-arrow" aria-hidden="true">
                            ${h.kind === 'succession' ? '⇒' : '→'}
                          </span>
                          ${h.toKeepers.map((target) => html`
                            <${KeeperBadge} key=${target} id=${target} size="sm" portrait=${knownKeeperSet.has(target)} />
                          `)}
                        `}
                        <span class="pulse-handoff-title">${h.title}</span>
                        <span class="pulse-pill" data-tone=${h.kind === 'succession' ? 'brass' : 'info'}>
                          ${h.kind === 'succession' ? 'Succession' : h.kind === 'handoff' ? 'Handoff' : `${h.replyCount} replies`}
                        </span>
                      </button>
                    `)}
                  </div>
                `}
          </section>
        </div>

        <div class="pulse-col">
          <!-- Attention Queue Card -->
          <section class="pulse-card" aria-label="주의 필요 대기열">
            <div class="pulse-card-head">
              <div class="pulse-card-title-group">
                <h2>Attention Queue</h2>
                <span class="pulse-pill" data-tone="warn" data-stale=${attentionStale ? 'true' : 'false'} aria-hidden=${attentionStale ? undefined : 'true'}>지연됨</span>
              </div>
              <div class="pulse-header-meta">
                <span class="pulse-pill" data-tone=${attentionPillTone}>
                  ${attentionPillText}
                </span>
                <button type="button" class="btn-ghost" onClick=${() => props.onNavigate('/work/inbox')}>
                  Inbox →
                </button>
              </div>
            </div>
            ${attentionErrors.length > 0 && html`
              <div class="ap-error" role="alert">${attentionErrors.join(' · ')}</div>
            `}
            ${attentionUnchecked.length > 0 && html`
              <div class="pulse-empty" role="note" data-attention-unchecked="true">
                미확인 소스: ${attentionUnchecked.join(' · ')}
              </div>
            `}
            ${attentionLoading && attentionItems.length === 0
              ? html`<div class="pulse-empty">대기열 불러오는 중…</div>`
              : attentionItems.length === 0
                ? (attentionErrors.length > 0
                    ? html`<div class="pulse-empty">일부 소스 조회 실패로 대기열을 확정할 수 없습니다</div>`
                    : attentionUnchecked.length > 0
                      ? html`<div class="pulse-empty">확인된 Keeper 오류는 없으나 미확인 대기열이 있어 비어 있음으로 확정할 수 없습니다</div>`
                      : html`<div class="pulse-empty">대기 중인 승인·질문·오류 없음</div>`)
                : html`
                  <div class="pulse-attn-list">
                    ${attentionItems.slice(0, 10).map((item) => html`
                      <div key=${item.id} class="pulse-attn-row" data-sev=${item.severity}>
                        <div class="pulse-attn-main">
                          <span class="pulse-attn-title" title=${item.title}>
                            ${item.severity === 'critical' ? '⚠ ' : ''}${item.title}
                          </span>
                          <span class="pulse-attn-detail" title=${`${item.keeper} · ${item.detail}`}>${item.keeper} · ${item.detail}</span>
                        </div>
                        <div class="pulse-attn-actions">
                          <span class="pulse-pill">${formatRelativeAge(item.ageSec)}</span>
                          ${item.expiresInSec !== null && html`
                            <span class="pulse-pill" data-tone=${item.expiresInSec > 0 ? 'warn' : 'bad'}>
                              ${formatApprovalExpiry(item.expiresInSec)}
                            </span>
                          `}
                          <button
                            type="button"
                            class="btn-ghost"
                            onClick=${() => {
                              const row = item.raw
                              if (item.kind === 'keeper_failure' && isPulseKeeperRow(row)) {
                                props.onInspect({
                                  title: item.title,
                                  subtitle: item.keeper,
                                  kind: item.kind,
                                  data: row,
                                  render: () => renderPulseKeeperErrorDetail(row),
                                })
                              } else {
                                props.onInspect({
                                  title: item.title,
                                  subtitle: item.keeper,
                                  kind: item.kind,
                                  data: row,
                                })
                              }
                            }}
                          >
                            미리보기
                          </button>
                          <button
                            type="button"
                            class="btn-primary"
                            onClick=${() => props.onNavigate(item.route)}
                          >
                            이동
                          </button>
                        </div>
                      </div>
                    `)}
                  </div>
                `}
          </section>

          <!-- Active Goals -->
          <section class="pulse-card" aria-label="진행 중인 Goals">
            <div class="pulse-card-head">
              <div class="pulse-card-title-group">
                <h2>Active Goals</h2>
                <span class="pulse-pill" data-tone="warn" data-stale=${bundle.goals.kind === 'value' && bundle.goals.stale ? 'true' : 'false'} aria-hidden=${bundle.goals.kind === 'value' && bundle.goals.stale ? undefined : 'true'}>지연됨</span>
              </div>
              <div class="pulse-header-meta">
                ${goalsSnapshot?.state === 'approval_queue_unavailable' && html`
                  <span class="pulse-pill" data-tone="bad">승인 대기열 읽기 실패</span>
                `}
                ${goalsSnapshot?.state === 'ready' && goalsSnapshot.pending_approval_total !== null && html`
                  <span class="pulse-pill" data-tone=${goalsSnapshot.pending_approval_total > 0 ? 'warn' : 'default'}>
                    승인 대기 ${goalsSnapshot.pending_approval_total}
                  </span>
                `}
                <button type="button" class="btn-ghost" onClick=${() => props.onNavigate('/work/goals')}>
                  Goals →
                </button>
              </div>
            </div>
            ${bundle.goals.kind === 'loading'
              ? html`<div class="pulse-empty">Goal 목록 불러오는 중…</div>`
              : bundle.goals.kind === 'failed'
                ? html`<div class="ap-error" role="alert">Goal 조회 실패: ${bundle.goals.error.message}</div>`
                : goalsSnapshot?.state === 'approval_queue_unavailable'
                  ? html`<div class="ap-error" role="alert">승인 대기열을 읽지 못해 Goal 목록과 승인 수를 확인할 수 없습니다: ${goalsSnapshot.title} (${goalsSnapshot.detail})</div>`
                : goalsSnapshot === null
                  ? html`<div class="pulse-empty">${formatObserved(bundle.goals)}</div>`
                : activeGoals.length === 0
                  ? html`<div class="pulse-empty">활성 Goal 없음</div>`
                  : html`
                    <div class="pulse-goal-list">
                      ${activeGoals.map((g) => html`
                        <button
                          key=${g.id}
                          type="button"
                          class="pulse-goal-row"
                          onClick=${() => props.onNavigate(`/work/goals/${encodeURIComponent(g.id)}`)}
                        >
                          <span class="pulse-goal-title" title=${g.title}>${g.title}</span>
                          <div class="pulse-goal-badges">
                            <span class="pulse-pill" data-tone=${g.phase === null ? 'default' : goalPhaseTone(g.phase)} title=${g.phase ?? '서버가 phase 를 보내지 않음'}>
                              ${g.phase ?? 'phase 미확인'}
                            </span>
                            <span class="pulse-pill">
                              ${g.task_done_count}/${g.task_count}
                            </span>
                            ${g.pending_approval_count > 0 && html`
                              <span class="pulse-pill" data-tone="warn" title=${g.sub_goal_count > 0 ? `하위 Goal ${g.sub_goal_count}개 포함` : '이 Goal 의 승인 대기'}>
                                승인 ${g.pending_approval_count}
                              </span>
                            `}
                            ${g.awaiting_verification_count > 0 && html`
                              <span class="pulse-pill" data-tone="warn">
                                검증 ${g.awaiting_verification_count}
                              </span>
                            `}
                          </div>
                        </button>
                      `)}
                    </div>
                  `}
          </section>

          <!-- World Memory & Candle Pulse Digest (flat cards, no nested h2 or double padding) -->
          ${(() => {
            const worldMemoryCard = html`
              <section class="pulse-card" aria-label="World Memory">
                <div class="pulse-card-head">
                  <h2>World Memory</h2>
                  <button type="button" class="btn-ghost" onClick=${() => props.onNavigate('/knowledge/memory')}>
                    Memory →
                  </button>
                </div>
                ${bundle.worldMemory.kind === 'failed'
                  ? html`<div class="ap-error" role="alert">World Memory 조회 실패: ${bundle.worldMemory.error.message}</div>`
                  : worldMemory === null
                    ? html`<div class="pulse-empty">${formatObserved(bundle.worldMemory)}</div>`
                    : html`
                      <div class="pulse-kv-grid">
                        <div class="pulse-kv">
                          <span class="pulse-kv-k">Claims</span>
                          <span class="pulse-kv-v">${formatCompactCount(worldMemory.claims_count).short}</span>
                        </div>
                        <div class="pulse-kv">
                          <span class="pulse-kv-k">Facts</span>
                          <span class="pulse-kv-v">${formatCompactCount(worldMemory.facts_count).short}</span>
                        </div>
                        <div class="pulse-kv">
                          <span class="pulse-kv-k">Conflicts</span>
                          <span class="pulse-kv-v">${worldMemory.conflicts_count}</span>
                        </div>
                        <div class="pulse-kv">
                          <span class="pulse-kv-k">Wiki Pages</span>
                          <span class="pulse-kv-v">
                            ${worldMemory.wiki_count !== null ? worldMemory.wiki_count : '없음'}
                          </span>
                        </div>
                      </div>
                    `}
              </section>
            `

            if (showCandleBalance && candleDigest !== null) {
              return html`
                <div class="pulse-digest-grid" aria-label="World Memory 및 Candle 요약">
                  ${worldMemoryCard}
                  <section class="pulse-card" data-accent="brass" aria-label="Candle Economy">
                    <div class="pulse-card-head">
                      <h2>Candle Economy</h2>
                      <button type="button" class="btn-ghost" onClick=${() => props.onNavigate('/work/candle')}>
                        Candle →
                      </button>
                    </div>
                    <div class="pulse-kv-grid">
                      <div class="pulse-kv">
                        <span class="pulse-kv-k">Circulating</span>
                        <span class="pulse-kv-v">
                          ${formatObserved(formatMilliCandle(candleDigest.circulating_milli))} C
                        </span>
                      </div>
                      <div class="pulse-kv">
                        <span class="pulse-kv-k">Holders</span>
                        <span class="pulse-kv-v">${candleDigest.active_keepers}</span>
                      </div>
                      <div class="pulse-kv">
                        <span class="pulse-kv-k">Events</span>
                        <span class="pulse-kv-v">${candleDigest.total_events}</span>
                      </div>
                      <div class="pulse-kv">
                        <span class="pulse-kv-k">Half-life</span>
                        <span class="pulse-kv-v">
                          ${candleDigest.half_life_hours !== null ? `${candleDigest.half_life_hours}h` : '없음'}
                        </span>
                      </div>
                    </div>
                  </section>
                </div>
              `
            }

            const candleEmptyStatus = bundle.candle.kind === 'failed'
              ? `조회 실패: ${bundle.candle.error.message}`
              : candleDigest === null
                ? formatObserved(bundle.candle)
                : candleDigest.policy_configuration === 'enabled'
                  ? '발행된 Candle 원장 기록 없음'
                  : `Candle 정책 비활성 (${candleDigest.policy_configuration}${candleDigest.disabled_reason ? `: ${candleDigest.disabled_reason}` : ''})`

            return html`
              ${worldMemoryCard}
              <details
                class="ap-disclosure pulse-candle-disclosure"
                data-testid="pulse-candle-disclosure"
                aria-label="Candle Economy"
              >
                <summary class="ap-disclosure-trigger">
                  <span>Candle Economy · ${candleEmptyStatus}</span>
                  <span aria-hidden="true">▸</span>
                </summary>
                <div class="ap-disclosure-body">
                  <div class="pulse-card-head">
                    ${bundle.candle.kind === 'failed'
                      ? html`<div class="ap-error" role="alert">Candle 조회 실패: ${bundle.candle.error.message}</div>`
                      : html`<span class="pulse-empty">${candleEmptyStatus}</span>`}
                    <button type="button" class="btn-ghost" onClick=${() => props.onNavigate('/work/candle')}>
                      Candle →
                    </button>
                  </div>
                </div>
              </details>
            `
          })()}
        </div>
      </div>
    </div>
  `
}

export default PulseWorkspace
